def solve(s: str) -> bool:
    """Return True if all brackets in *s* are balanced.

    The function considers three types of brackets: (), [], {}. All other
    characters are ignored. A string is considered balanced when every opening
    bracket has a corresponding closing bracket of the same type and the pairs
    are properly nested.
    """
    # Mapping of opening to closing brackets
    opening = {'(': ')', '[': ']', '{': '}'}
    closing = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in closing:
            if not stack:
                return False
            if stack[-1] != closing[ch]:
                return False
            stack.pop()
        # ignore other characters
    return not stack

