def solve(grid):
    if not grid:
        return 0
    g = [list(row) for row in grid]
    rows = len(g)
    count = 0
    for i in range(rows):
        for j in range(len(g[i])):
            if g[i][j] == 1:
                count += 1
                stack = [(i, j)]
                g[i][j] = 0
                while stack:
                    r, c = stack.pop()
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < len(g[nr]) and g[nr][nc] == 1:
                            g[nr][nc] = 0
                            stack.append((nr, nc))
    return count
```

