def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either an integer or an operator '+', '-', '*', '/'.
    Returns integer result, where division truncates toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

